import type { PackOptions, UnpackResult } from './types';

export class FaustPiecePackager {
  async unpack(data: Uint8Array | ArrayBuffer, fileName: string): Promise<UnpackResult> {
    const JSZip = (await import('jszip')).default;
    const zip = await JSZip.loadAsync(data);
    const baseName = fileName.replace(/\.FaustPiece$/i, '');
    const mainDspName = `${baseName}.dsp`;
    const mainDspFile = zip.file(mainDspName);
    if (!mainDspFile) throw new Error(`Invalid .FaustPiece: missing main DSP file "${mainDspName}"`);
    const mainDspContent = await mainDspFile.async('string');
    const attachments: string[] = [];
    zip.forEach((relativePath) => { if (relativePath !== mainDspName) attachments.push(relativePath); });
    return { mainDspPath: mainDspName, mainDspContent, attachments, tempDir: '' };
  }

  async pack(options: PackOptions, attachmentContents: Map<string, Uint8Array | string> = new Map()): Promise<Uint8Array> {
    const JSZip = (await import('jszip')).default;
    const zip = new JSZip();
    const mainDspName = `${options.outputName}.dsp`;
    zip.file(mainDspName, options.dspContent);
    for (const [filename, content] of attachmentContents) {
      const isAudio = /\.(wav|aif|aiff|flac)$/i.test(filename);
      const isLib = filename.endsWith('.dsp') && filename !== mainDspName;
      if (isAudio && !options.includeAudio) continue;
      if (isLib && !options.includeLibs) continue;
      zip.file(filename, content);
    }
    return zip.generateAsync({ type: 'uint8array' });
  }
}
