import type { ValidationResult } from './types';

export class FileNameValidator {
  validate(name: string): ValidationResult {
    if (!name || name.length === 0) return { valid: false, error: 'File name cannot be empty.' };
    if (name.includes(' ')) return { valid: false, error: 'File name must not contain spaces.' };
    return { valid: true };
  }
}
