/**
 * parseParams.ts
 *
 * Robust DSP parameter extraction from Faust source code.
 *
 * Handles all label formats:
 *   "freq"                          → paramPath: "freq"
 *   "[3]Resonance[acc:2 1 -10 0 12]" → paramPath: "[3]Resonance"  (display: "Resonance")
 *   "h:[1]Instrument Hands/1 (Note %b)[acc:...]" → paramPath: "h:[1]Instrument Hands/1 (Note %b)"
 *   "Wah Wah[acc:0 1 -10 0 10]"    → paramPath: "Wah Wah"
 *
 * The paramPath is the full label text BEFORE the first metadata block,
 * which is what DSPMetadataEditor uses to locate the label in the source.
 */

export interface ParsedParam {
  /** The full label prefix before any [...] metadata — used as the key for upsert/remove */
  paramPath: string;
  /** Human-readable display name (strips leading [N] ordering prefixes and group paths) */
  displayName: string;
  /** Raw full label string as it appears in the source (between the outer quotes) */
  fullLabel: string;
}

function maskComments(code: string): string {
  let masked = '';
  let state: 'code' | 'lineComment' | 'blockComment' | 'string' = 'code';
  let escaped = false;

  for (let i = 0; i < code.length; i++) {
    const ch = code[i];
    const next = code[i + 1];

    if (state === 'lineComment') {
      if (ch === '\n') {
        state = 'code';
        masked += ch;
      } else {
        masked += ' ';
      }
      continue;
    }

    if (state === 'blockComment') {
      if (ch === '*' && next === '/') {
        masked += '  ';
        i++;
        state = 'code';
      } else {
        masked += ch === '\n' ? ch : ' ';
      }
      continue;
    }

    if (state === 'string') {
      masked += ch;
      if (escaped) {
        escaped = false;
      } else if (ch === '\\') {
        escaped = true;
      } else if (ch === '"') {
        state = 'code';
      }
      continue;
    }

    if (ch === '/' && next === '/') {
      masked += '  ';
      i++;
      state = 'lineComment';
    } else if (ch === '/' && next === '*') {
      masked += '  ';
      i++;
      state = 'blockComment';
    } else {
      masked += ch;
      if (ch === '"') state = 'string';
    }
  }

  return masked;
}

/**
 * Extract all DSP UI parameters from Faust source code.
 * Masks comments first, then finds all hslider/vslider/button/etc. labels.
 */
export function parseParams(code: string): ParsedParam[] {
  const stripped = maskComments(code);

  const results: ParsedParam[] = [];
  const seen = new Set<string>();

  // Match the full label string inside the first string argument of any UI widget
  // The label can contain anything including [ ] metadata blocks
  const widgetRegex = /(?:hslider|vslider|button|checkbox|nentry|hbargraph|vbargraph)\s*\(\s*"((?:[^"\\]|\\.)*)"/g;
  let m: RegExpExecArray | null;

  while ((m = widgetRegex.exec(stripped)) !== null) {
    const fullLabel = m[1];

    // paramPath = everything before the first [ metadata block
    // e.g. "[3]Resonance[acc:...]" → "[3]Resonance"
    // e.g. "Wah Wah[acc:...]"      → "Wah Wah"
    // e.g. "h:[1]Hands/1[acc:...]" → "h:[1]Hands/1"
    // Metadata blocks contain a colon: [key:value]. Ordering prefixes [1],[2] do NOT.
    const metaStart = fullLabel.search(/\[(?:SHCUI|acc|gyr|motion|showName|style|unit|hidden|tooltip|scale|integer|log|lin|knob|led|numerical|menu|radio|type|osc|midi|screencolor)[^\]]*\]/);
    const paramPath = metaStart !== -1
      ? fullLabel.slice(0, metaStart).trimEnd()
      : fullLabel;

    if (!paramPath || seen.has(paramPath)) continue;
    seen.add(paramPath);

    // displayName: strip leading [N] ordering prefix and group path separators
    // "[3]Resonance" → "Resonance"
    // "h:[1]Instrument Hands/1 (Note %b)" → "Instrument Hands/1 (Note %b)"
    let displayName = paramPath
      .replace(/^(?:[a-z]:\s*)?(?:\[[^\]]*\])+\s*/i, '')  // strip leading [N] or h:[N]
      .replace(/^[a-z]:\s*/i, '')                           // strip remaining group prefix like "h:"
      .trim();
    if (!displayName) displayName = paramPath;

    results.push({ paramPath, displayName, fullLabel });
  }

  return results;
}
